import { useTranslation } from 'react-i18next';
import { Link } from '../ui/link';
import { Center, HStack, Stack } from 'styled-system/jsx';
import { Text } from '~/components/ui/text';
import type { Event } from '~/types/bluebird';
import { getYouTubeVideoId } from '~/utils/url'; // Assuming this utility is available

interface EventDisplayProps {
  event: Event;
  useEnglish?: boolean;
}

export function EventDisplay({ event, useEnglish }: EventDisplayProps) {
  const { t } = useTranslation();

  return (
    <Stack key={event.id} borderColor="gray.200" borderRadius="md" borderWidth="1px" p="4">
      <HStack
        flexDir={{ base: 'column', sm: 'row' }}
        justifyContent="center"
        alignContent="center"
        alignItems="center"
      >
        <Stack gap={1} flexShrink="1" alignItems="flex-start">
          <Text fontWeight="bold">{useEnglish && event.titleEn ? event.titleEn : event.title}</Text>
          <Text color="fg.subtle" fontSize="sm">
            {new Date(event.eventDate).toLocaleString([], {
              year: 'numeric',
              month: 'numeric',
              day: 'numeric',
              hour: '2-digit',
              minute: '2-digit'
            })}
          </Text>
          {event.eventType === 'text' && (
            <Text fontSize="sm">
              {t('bluebird.events.display.contentLabel')} {event.content}
            </Text>
          )}
          {event.eventType === 'youtube' && event.content && (
            <Link href={event.content} target="_blank" fontSize="sm">
              {event.content}
            </Link>
          )}
        </Stack>
        {event.eventType === 'youtube' && event.content && (
          <Center mt="2">
            <iframe
              width="300"
              height="200"
              src={`https://www.youtube.com/embed/${getYouTubeVideoId(event.content)}`}
              allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
              allowFullScreen
              title="YouTube video player"
            ></iframe>
          </Center>
        )}
      </HStack>
    </Stack>
  );
}
