import type { Virtualizer } from '@tanstack/react-virtual';

export const findClosestVirtualItemToTop = (
  scrollElement: HTMLElement,
  virtualizer: Virtualizer<HTMLDivElement, Element>,
  offset: number = 0
) => {
  const viewportTop = scrollElement.scrollTop - offset;
  const viewportBottom = scrollElement.scrollTop + scrollElement.clientHeight - offset;

  const virtualItems = virtualizer.getVirtualItems();
  if (!virtualItems.length) {
    return null;
  }

  for (const item of virtualItems) {
    if (item.start >= viewportTop && item.end <= viewportBottom) {
      return item;
    }
  }

  for (const item of virtualItems) {
    if (item.start + item.size / 2 >= viewportTop) {
      return item;
    }
  }

  return virtualItems[virtualItems.length - 1];
};
